"""RoboPaint stroke-copy. All robot state comes from the public client/cameras.
Target plans contain separate, open brush sweeps; no area-filling trajectories.
"""
import sys, os, json, time, math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output')
class Painter:
 def __init__(self):
  self.r=Robot(); self.spec=self.r.spec(); self.o=self.r.get_obs(cameras=[],video='none');self.pos=np.array(self.o.meta['proprio']['now'][7:10]);self.quat=[0,1,0,0]; self.rows=[];self.color=None
 def send(self,rows,dt=.05,cameras=[]):
  before=self.r.status()
  try: res=self.r.submit('ee_pose',rows,dt=dt,cameras=cameras,video='none')
  except Exception:
   self.r.wait_ready();after=self.r.status()
   if after['calls']==before['calls']:res=self.r.submit('ee_pose',rows,dt=dt,cameras=cameras,video='none')
   else:res=self.r.get_obs(cameras=cameras,video='none')
  self.o=res
  if res.meta.get('stopped'):raise RuntimeError('partial submit')
  if any(p.get('ik_failures',0) for p in res.meta.get('plan',[])): print('IK WARNING',res.meta['plan'],flush=True)
  with open(OUT/'actions.jsonl','a') as f:f.write(json.dumps({'rows':np.asarray(rows).tolist(),'dt':dt,'meta':res.meta})+'\n')
  return res
 def goto(self,p,speed=.15,hold=.2):
  p=np.array(p); n=max(1,math.ceil(np.linalg.norm(p-self.pos)/speed/.05));rows=[list(self.pos+(p-self.pos)*(i+1)/n)+self.quat for i in range(n)]
  rows += [list(p)+self.quat]*round(hold/.05)
  for j in range(0,len(rows),190):self.send(rows[j:j+190])
  self.pos=p
 def dip(self,c):
  if self.color==c:return
  self.goto([self.pos[0],self.pos[1],.075]);i=c-1
  p=[-.16+.03*(i%5),.145+.03*(i//5),.075]
  self.goto(p);self.goto([p[0],p[1],.024],speed=.08,hold=.4);self.goto(p,speed=.08)
  self.color=c
 def sweep(self,points,depth=.004,practice=False,speed=.04):
  # points in image pixels, or practice sheet millimetres.
  points=np.array(points,float)
  if practice: xyz=np.c_[.0135925-points[:,1]/1000,-.1359035-points[:,0]/1000,np.full(len(points),.0202-depth)]
  else:xyz=np.c_[.0135925-(points[:,1]+.5)*.227185/1024,.1135925-(points[:,0]+.5)*.227185/1024,np.full(len(points),.0202-depth)]
  if np.ndim(depth)>0:xyz[:,2]=.0202-np.asarray(depth)
  self.goto([xyz[0,0],xyz[0,1],.045],hold=.15)
  self.goto(xyz[0],speed=.055,hold=.15)
  for p in xyz[1:]:self.goto(p,speed=speed,hold=0)
  self.goto(xyz[-1],speed=speed,hold=.15)
  self.goto([xyz[-1,0],xyz[-1,1],.045],speed=.055,hold=.15)
 def park(self,name):
  self.goto([-.3,0,.22],hold=.5)
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam'],video='none');o.save(str(OUT/name))
  for c,im in o.last.items():Image.fromarray(im).save(OUT/(name+'_'+c+'.png'))
  print('STATUS',self.r.status(),flush=True)
if __name__=='__main__':
 import argparse
 ap=argparse.ArgumentParser();ap.add_argument('mode');ap.add_argument('--plan');ap.add_argument('--start',type=int,default=0);ap.add_argument('--end',type=int);a=ap.parse_args()
 p=Painter()
 if a.mode=='practice':
  p.dip(6)
  for i,d in enumerate([.0005,.001,.002,.0035,.005,.0075,.010,.012]):
   p.sweep([[15,15+i*26],[82,15+i*26]],depth=d,practice=True);print('practice',i,d,flush=True)
  p.park('practice1')
 elif a.mode=='paint':
  plan=json.load(open(a.plan));end=len(plan) if a.end is None else a.end
  for i in range(a.start,end):
   s=plan[i];p.dip(s['color']);p.sweep(s['points'],s['depth'],speed=s.get('speed',.04))
   (OUT/'progress.json').write_text(json.dumps({'completed':i,'plan':a.plan}))
   print('STROKE',i+1,'/',len(plan),'color',s['color'],flush=True)
  p.park('paint_'+str(end))
 elif a.mode=='park':p.park('park')
