import numpy as np
from PIL import Image,ImageDraw
from scipy.ndimage import gaussian_filter
COLORS=np.array([[248,244,236],[228,210,169],[179,188,173],[194,171,128],[149,150,135],[156,133,104],[85,113,136],[109,104,90],[73,97,115],[137,38,29],[55,54,50]])
def rgb2lab(rgb):
 a=np.where(rgb>.04045,((rgb+.055)/1.055)**2.4,rgb/12.92)
 xyz=a@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]).T
 xyz/=np.array([.95047,1,1.08883]);f=np.where(xyz>.008856,xyz**(1/3),7.787*xyz+16/116)
 return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],axis=-1)
def rectify(path,N=512):
 return np.array(Image.open(path).crop((68,68,956,956)).resize((N,N),Image.Resampling.BOX))
def classify_camera(im):
 # Observed paper and known paint swatch transfer, in camera RGB.
 observed=np.array([[224,222,211],[207,191,152],[161,172,157],[175,155,115],[134,137,122],[141,121,93],[77,104,126],[98,94,80],[66,89,105],[124,33,25],[49,48,44]])
 d=((im[:,:,None,:].astype(float)-observed)**2).sum(3)
 return d.argmin(2)
def classify_target(im):
 lab=rgb2lab(im/255.);cl=rgb2lab(COLORS[None]/255.)[0]
 return ((lab[:,:,None]-cl)**2).sum(3).argmin(2)
def metrics(target,paint,mmpp):
 a=rgb2lab(gaussian_filter(target.astype(float),(1/mmpp,1/mmpp,0))/255.)
 b=rgb2lab(gaussian_filter(paint.astype(float),(1/mmpp,1/mmpp,0))/255.)
 diff=np.linalg.norm(a-b,axis=2)
 return {'mean_lab_estimate':float(diff.mean()),'p90_lab_estimate':float(np.percentile(diff,90))}
if __name__=='__main__':
 import sys,json
 p=sys.argv[1];im=rectify(p);labels=classify_camera(im);paint=COLORS[labels]
 Image.fromarray(paint.astype('uint8')).resize((1024,1024)).save('/app/output/camera_classified.png')
 target=np.array(Image.open('/app/target.png').resize((512,512),Image.Resampling.BOX))[:,:,:3]
 print(json.dumps(metrics(target,paint,227.185/512)))
